// Champion names and icons. The list is data/champions.json (generated by
// tools/mock_stats.py from Riot's Data Dragon); icons load from the Data
// Dragon CDN for that version.

import data from "../../../../data/champions.json";

export type ChampionInfo = {
  id: number;
  name: string;
  /** Data Dragon name, used in icon URLs ("MonkeyKing" for Wukong). */
  alias: string;
  tags: string[];
};

export type ChampionData = { version: string; champions: ChampionInfo[] };

const DDRAGON = "https://ddragon.leagueoflegends.com/cdn";

export class Champions {
  readonly version: string;
  /** Sorted by name. */
  readonly list: readonly ChampionInfo[];
  private readonly byId: Map<number, ChampionInfo>;

  constructor(d: ChampionData) {
    this.version = d.version;
    this.list = [...d.champions].sort((a, b) => a.name.localeCompare(b.name));
    this.byId = new Map(d.champions.map((c) => [c.id, c]));
  }

  get(id: number | null | undefined): ChampionInfo | undefined {
    return id == null ? undefined : this.byId.get(id);
  }

  /** The champion's name, or `#<id>` for one the list doesn't know yet. */
  name(id: number): string {
    return this.byId.get(id)?.name ?? `#${id}`;
  }

  icon(id: number): string | undefined {
    const c = this.byId.get(id);
    return c && `${DDRAGON}/${this.version}/img/champion/${c.alias}.png`;
  }

  /** Name search, case- and accent-insensitive, ignoring spaces and punctuation. */
  search(query: string): ChampionInfo[] {
    const q = fold(query);
    return q ? this.list.filter((c) => fold(c.name).includes(q)) : [...this.list];
  }
}

function fold(s: string): string {
  return s
    .normalize("NFD")
    .replace(/[^\p{Letter}\p{Number}]/gu, "")
    .toLowerCase();
}

/** The bundled champion list. */
export const champions = new Champions(data as ChampionData);
